import app from 'flarum/forum/app';
/*
 * 🚨 FormModal, not Modal. In Flarum 2 the base Modal renders no <form>, so a
 * submit button inside it submits nothing and `onsubmit` is never called.
 */
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Stream from 'flarum/common/utils/Stream';
import extractText from 'flarum/common/utils/extractText';
import { emptyFields, isEmpty, parse, serialize } from '../common/source';

/** A field the admin defined (src/Fields.php), as the forum payload carries it. */

export function fieldDefinitions() {
  const list = app.forum.attribute('recipesFields');
  return Array.isArray(list) ? list : [];
}
function t(key) {
  return extractText(app.translator.trans(`ernestdefoe-recipes.lib.composer.${key}`));
}

/**
 * The form behind every editor's Recipe button: the plain composer, FoF Rich
 * Text and Scribe all open this, and all receive the same text back. Only how
 * that text is put into the post differs.
 */
export default class RecipeModal extends FormModal {
  fields = {};
  definitions = [];
  extra = {};
  /** Header values with no box in the form (a field since removed): carried through untouched. */
  hidden = {};
  uploading = false;
  dragging = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.definitions = fieldDefinitions();
    const keys = this.definitions.map(field => field.key);
    const initial = this.attrs.body ? parse(this.attrs.body, keys) : emptyFields();
    for (const key of Object.keys(initial)) {
      if (key !== 'extra') this.fields[key] = Stream(initial[key]);
    }
    for (const field of this.definitions) this.extra[field.key] = Stream(initial.extra[field.key] ?? '');
    for (const [key, value] of Object.entries(initial.extra)) if (!keys.includes(key)) this.hidden[key] = value;
  }

  /**
   * The photo: uploaded here (when the member may), or a web address (when the
   * admin allows them). The server decides both again when the post is saved.
   */
  photoField() {
    const canUpload = !!app.forum.attribute('canUploadRecipePhotos');
    const urls = app.forum.attribute('recipesImageUrls') !== false;
    const image = this.fields.image().trim();

    // Nothing this member could add: the field would only be in the way.
    if (!canUpload && !urls && !image) return null;
    const isUpload = image.startsWith(String(app.forum.attribute('baseUrl')) + '/assets/recipes/');
    const pick = files => files?.[0] && this.upload(files[0]);
    return m("div", {
      className: "Form-group RecipeModal-photo"
    }, m("label", {
      for: urls ? 'recipe-image' : 'recipe-photo'
    }, t('image')), image && /^https?:\/\//i.test(image) ? m("div", {
      className: "RecipeModal-photoPreview"
    }, m("img", {
      src: image,
      alt: ""
    }), m(Button, {
      className: "Button Button--icon Button--flat",
      icon: "fas fa-times",
      "aria-label": t('image_remove'),
      title: t('image_remove'),
      onclick: () => this.fields.image('')
    })) : null, canUpload ? m("div", {
      className: 'RecipeModal-drop' + (this.dragging ? ' is-dragging' : ''),
      ondragover: e => {
        e.preventDefault();
        this.dragging = true;
      },
      ondragleave: () => this.dragging = false,
      ondrop: e => {
        e.preventDefault();
        this.dragging = false;
        pick(e.dataTransfer?.files);
      }
    }, m("input", {
      id: "recipe-photo",
      type: "file",
      accept: "image/jpeg,image/png,image/webp",
      className: "RecipeModal-file",
      disabled: this.uploading,
      onchange: e => {
        const input = e.target;
        pick(input.files);
        input.value = '';
      }
    }), m("i", {
      className: "icon fas fa-camera",
      "aria-hidden": "true"
    }), ' ', this.uploading ? t('image_uploading') : [t('image_drop'), ' ', m("label", {
      for: "recipe-photo",
      className: "RecipeModal-choose"
    }, t('image_choose'))]) : null, urls ? m("input", {
      id: "recipe-image",
      className: "FormControl",
      type: "url",
      inputmode: "url",
      placeholder: canUpload ? t('image_url_placeholder') : 'https://',
      "aria-label": canUpload ? t('image_url_placeholder') : undefined,
      value: isUpload ? '' : image,
      oninput: e => this.fields.image(e.target.value)
    }) : image && !isUpload ? m("div", {
      className: "helpText"
    }, t('image_kept')) : null, m("div", {
      className: "helpText"
    }, t('image_help')));
  }
  upload(file) {
    // Mirrors Photos\PhotoValidator, to save a pointless upload; the server checks the bytes.
    if (!/^image\/(jpeg|png|webp)$/.test(file.type)) {
      this.alertAttrs = {
        type: 'error',
        content: t('image_type')
      };
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      this.alertAttrs = {
        type: 'error',
        content: t('image_too_big')
      };
      return;
    }
    const body = new FormData();
    body.append('photo', file);
    this.uploading = true;
    this.alertAttrs = null;
    app.request({
      method: 'POST',
      url: app.forum.attribute('apiUrl') + '/recipes/photos',
      serialize: raw => raw,
      body
    }).then(response => this.fields.image(response.url)).catch(() => {}).finally(() => {
      this.uploading = false;
      m.redraw();
    });
    m.redraw();
  }
  className() {
    return 'RecipeModal Modal--medium';
  }
  title() {
    return t(this.attrs.mode === 'remix' ? 'remix_title' : this.attrs.body ? 'edit_title' : 'title');
  }
  content() {
    const f = this.fields;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-title"
    }, t('name')), m("input", {
      id: "recipe-title",
      className: "FormControl",
      maxlength: 200,
      placeholder: t('name_placeholder'),
      bidi: f.title
    })), m("div", {
      className: "RecipeModal-row"
    }, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-servings"
    }, t('servings')), m("input", {
      id: "recipe-servings",
      className: "FormControl",
      type: "number",
      min: "1",
      max: "999",
      inputmode: "numeric",
      bidi: f.servings
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-prep"
    }, t('prep')), m("input", {
      id: "recipe-prep",
      className: "FormControl",
      placeholder: t('time_placeholder'),
      bidi: f.prep
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-cook"
    }, t('cook')), m("input", {
      id: "recipe-cook",
      className: "FormControl",
      placeholder: t('time_placeholder'),
      bidi: f.cook
    }))), this.definitions.length ? m("div", {
      className: "RecipeModal-row RecipeModal-facts"
    }, this.definitions.map(field => m("div", {
      className: "Form-group"
    }, m("label", {
      for: `recipe-field-${field.key}`
    }, field.label, field.unit ? ` (${field.unit})` : ''), m("input", {
      id: `recipe-field-${field.key}`,
      className: "FormControl",
      inputmode: "decimal",
      placeholder: t(field.scope === 'recipe' ? 'field_recipe' : 'field_serving'),
      bidi: this.extra[field.key]
    })))) : null, this.photoField(), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-description"
    }, t('description')), m("textarea", {
      id: "recipe-description",
      className: "FormControl",
      rows: 2,
      bidi: f.description
    })), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-ingredients"
    }, t('ingredients')), m("textarea", {
      id: "recipe-ingredients",
      className: "FormControl RecipeModal-list",
      rows: 6,
      bidi: f.ingredients
    }), m("div", {
      className: "helpText"
    }, t('ingredients_help'))), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "recipe-steps"
    }, t('steps')), m("textarea", {
      id: "recipe-steps",
      className: "FormControl RecipeModal-list",
      rows: 6,
      bidi: f.steps
    }), m("div", {
      className: "helpText"
    }, t('steps_help'))), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit"
    }, t(this.attrs.mode === 'remix' ? 'remix_insert' : this.attrs.body ? 'update' : 'insert')))));
  }

  /**
   * 🚨 These checks catch typos only. The server re-checks everything on text
   * this form never saw — a hand-written block, an import, an API client — and
   * that is the check that protects anyone (src/Recipe.php).
   */
  onsubmit(e) {
    e.preventDefault();
    const values = {
      extra: {}
    };
    for (const key of Object.keys(this.fields)) values[key] = this.fields[key]();
    for (const field of this.definitions) {
      const value = this.extra[field.key]().trim();
      if (!value) continue;
      // Mirrors Fields::number(): the server shows nothing it cannot read.
      if (!/^\d{1,7}(?:[.,]\d{1,3})?$/.test(value)) {
        this.alertAttrs = {
          type: 'error',
          content: extractText(app.translator.trans('ernestdefoe-recipes.lib.composer.invalid_number', {
            field: field.label
          }))
        };
        return;
      }
      values.extra[field.key] = value;
    }
    // The admin's fields first, in their order; values with no box after them.
    Object.assign(values.extra, this.hidden);
    if (isEmpty(values)) {
      this.alertAttrs = {
        type: 'error',
        content: t('empty')
      };
      return;
    }
    if (values.image.trim() && !/^https?:\/\/\S+$/i.test(values.image.trim())) {
      this.alertAttrs = {
        type: 'error',
        content: t('invalid_image')
      };
      return;
    }
    if (this.uploading) return;
    this.attrs.onsubmit(serialize(values), values);
    this.hide();
  }
}